function dkParse(record){
  record=String(record||'').replace(/\s+/g,' ').trim();
  var segs=record.split(';').map(function(s){return s.trim();}).filter(Boolean);
  var tags={};
  for(var i=0;i<segs.length;i++){
    var eq=segs[i].indexOf('=');
    if(eq<0) continue;
    var k=segs[i].slice(0,eq).trim().toLowerCase();
    var v=segs[i].slice(eq+1).trim();
    tags[k]=v;
  }
  return { version: tags.v||'', tags:tags, ok: !!(tags.v && tags.p) };
}
function dkKeyBits(p){
  if(!p) return 0;
  var clean=String(p).replace(/\s+/g,'');
  var bytes=Math.floor(clean.length*3/4);
  return bytes*8;
}
function dkScore(tags){
  var checks=[];
  function add(name,pass,weight){ checks.push({name:name,pass:!!pass,weight:weight}); }
  add('含 v=DKIM1 版本', /dkim1/i.test(tags.v||''), 10);
  add('含公钥 p=', !!tags.p, 30);
  add('指定密钥算法 k', !!tags.k, 10);
  var bits=dkKeyBits(tags.p);
  add('密钥长度 ≥ 1024', bits>=1024, 15);
  add('密钥长度 ≥ 2048', bits>=2048, 15);
  add('签名范围 t=s 已声明(可选)', !!tags.t, 10);
  add('哈希算法 h 已声明(可选)', !!tags.h, 10);
  var got=0,total=0;
  for(var j=0;j<checks.length;j++){ total+=checks[j].weight; if(checks[j].pass) got+=checks[j].weight; }
  var grade='F';
  if(got>=90)grade='A'; else if(got>=75)grade='B'; else if(got>=60)grade='C'; else if(got>=40)grade='D';
  return { score:got, max:total, grade:grade, bits:bits, checks:checks };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { dkParse:dkParse, dkKeyBits:dkKeyBits, dkScore:dkScore };
}
if (typeof window !== 'undefined') {
  window.DkimForgePure = { dkParse:dkParse, dkKeyBits:dkKeyBits, dkScore:dkScore };
}
